def is_not_prime(n):
    """Return True if n is not a prime number, False if n is prime."""
    if n < 2:
        return True
    if n < 4:
        return False
    if n % 2 == 0:
        return True
    i = 3
    while i * i <= n:
        if n % i == 0:
            return True
        i += 2
    return False

