def is_sublist(lst, sub):
    """Check whether the list `lst` contains `sub` as a contiguous sublist."""
    if not sub:
        return True
    n, m = len(lst), len(sub)
    for i in range(n - m + 1):
        if lst[i:i + m] == sub:
            return True
    return False

def comb_sort(nums):
    """Sort a list of elements using comb sort."""
    n = len(nums)
    gap = n
    swapped = True
    while gap != 1 or swapped:
        # Shrink the gap by a factor of ~1.3
        gap = (gap * 10) // 13
        if gap < 1:
            gap = 1
        swapped = False
        for i in range(n - gap):
            if nums[i] > nums[i + gap]:
                nums[i], nums[i + gap] = nums[i + gap], nums[i]
                swapped = True
    return nums

def is_samepatterns(colors, patterns):
    """
    Check whether the `colors` list follows the sequence given in the
    `patterns` array, i.e. there is a consistent one-to-one mapping
    between pattern elements and colors.

    Examples:
        is_samepatterns(["red","green","green"], ["a", "b", "b"]) == True
        is_samepatterns(["red","green","greenn"], ["a", "b", "b"]) == False
    """
    if len(colors) != len(patterns):
        return False

    pattern_to_color = {}
    color_to_pattern = {}
    for pattern, color in zip(patterns, colors):
        if pattern in pattern_to_color:
            if pattern_to_color[pattern] != color:
                return False
        else:
            pattern_to_color[pattern] = color

        if color in color_to_pattern:
            if color_to_pattern[color] != pattern:
                return False
        else:
            color_to_pattern[color] = pattern

    return True


if __name__ == "__main__":
    assert is_samepatterns(["red", "green", "green"], ["a", "b", "b"]) == True
    assert is_samepatterns(["red", "green", "greenn"], ["a", "b", "b"]) == False
    assert is_samepatterns(["red", "red", "red"], ["a", "a", "a"]) == True
    assert is_samepatterns(["red", "green", "red"], ["a", "b", "b"]) == False
    assert is_samepatterns(["red", "green"], ["a", "b", "b"]) == False
    assert is_samepatterns([], []) == True
    print("All tests passed.")

