def next_smallest_palindrome(num):
    """Return the smallest palindrome strictly greater than num.

    Example:
        next_smallest_palindrome(99) == 101
    """
    n = num + 1  # smallest value the answer could be
    if n < 0:
        return 0  # 0 is the smallest non-negative palindrome

    s = str(n)
    length = len(s)
    half = s[:(length + 1) // 2]

    def mirror(left, size):
        # Build a palindrome of `size` digits from its left half.
        if size % 2 == 0:
            return int(left + left[::-1])
        return int(left + left[:-1][::-1])

    # Candidate: mirror the left half of n onto the right half.
    candidate = mirror(half, length)
    if candidate >= n:
        return candidate

    # Otherwise bump the left half by one and mirror again.
    # (The left half can't be all 9s here, so its length is stable.)
    half = str(int(half) + 1)
    return mirror(half, length)

