def amicable_numbers_sum(limit):
    """Sum all amicable numbers from 1 to `limit` (inclusive).

    A pair of numbers (a, b) with a != b is amicable if the sum of the
    proper divisors of a equals b and the sum of the proper divisors of
    b equals a. Each member of such a pair within the range contributes
    to the total.
    """
    if not isinstance(limit, int):
        return "Input must be an integer!"
    if limit < 1:
        return "Input must be a positive integer!"

    def sum_proper_divisors(n):
        total = 0
        i = 1
        while i * i <= n:
            if n % i == 0:
                total += i
                other = n // i
                if other != i and other != n:
                    total += other
            i += 1
        return total

    amicable_sum = 0
    for i in range(1, limit + 1):
        j = sum_proper_divisors(i)
        if j != i and sum_proper_divisors(j) == i:
            amicable_sum += i
    return amicable_sum

import cmath


def angle_complex(a, b):
    """Get the angle (phase) of the complex number a + b."""
