def sum(a, b):
    """Return the sum of common divisors of two given numbers."""
    n = min(a, b)
    total = 0
    for i in range(1, n + 1):
        if a % i == 0 and b % i == 0:
            total += i
    return total


if __name__ == "__main__":
    assert sum(10, 15) == 6
    print(sum(10, 15))  # 6 (common divisors: 1, 5)

