def max_sum(arr):
    """
    Find the maximum sum of a bitonic subsequence of the given array.
    A bitonic sequence is first increasing and then decreasing.

    Approach:
    - inc[i]: maximum sum of an increasing subsequence ending at index i.
    - dec[i]: maximum sum of a decreasing subsequence starting at index i.
    - The answer is max over i of inc[i] + dec[i] - arr[i] (arr[i] counted once).
    """
    n = len(arr)
    if n == 0:
        return 0

    # Maximum sum of increasing subsequence ending at i
    inc = arr[:]
    for i in range(1, n):
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    # Maximum sum of decreasing subsequence starting at i
    dec = arr[:]
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if arr[j] < arr[i]:
                dec[i] = max(dec[i], dec[j] + arr[i])

    # Combine: peak element counted in both, subtract one copy
    return max(inc[i] + dec[i] - arr[i] for i in range(n))


if __name__ == "__main__":
    assert max_sum([1, 15, 51, 45, 33, 100, 12, 18, 9]) == 194
    print("All tests passed.")

