def max_sub_array_sum_repeated(a, n, k):
    """
    Find the largest sum of a contiguous subarray in the modified array
    formed by repeating the given array `a` (of length n) k times.

    Example:
        max_sub_array_sum_repeated([10, 20, -30, -1], 4, 3) == 30
    """
    a = list(a[:n])

    def kadane(arr):
        # Standard Kadane's algorithm: max sum of a non-empty contiguous subarray.
        best = float('-inf')
        cur = 0
        for x in arr:
            cur = x if cur < 0 else cur + x
            if cur > best:
                best = cur
        return best

    if k <= 0 or not a:
        return 0

    if k == 1:
        return max(0, kadane(a))

    total = sum(a)
    # Best subarray lying within at most two consecutive copies.
    best_two = kadane(a + a)

    if total > 0:
        # Full copies in the middle only help when the total sum is positive.
        return max(0, best_two + (k - 2) * total)
    return max(0, best_two)

