def flatten_list(nested_list):
    """Flatten a given nested list structure into a single flat list."""
    result = []
    for item in nested_list:
        if isinstance(item, list):
            result.extend(flatten_list(item))
        else:
            result.append(item)
    return result

def max_aggregate(students):
    """
    Calculate the maximum aggregate (total score) from a list of (name, score) tuples.

    Groups scores by name, sums them, and returns the (name, total) tuple
    with the highest aggregate. In case of a tie, the name encountered
    first is returned.
    """
    totals = {}
    for name, score in students:
        totals[name] = totals.get(name, 0) + score
    return max(totals.items(), key=lambda item: item[1])

def dict_depth(dic):
    """Find the depth of a dictionary.

    The depth is the maximum level of nested dictionaries, where an empty
    dictionary counts as depth 1.

    Example:
        dict_depth({'a':1, 'b': {'c': {'d': {}}}}) == 4
    """
    if isinstance(dic, dict):
        return 1 + (max(map(dict_depth, dic.values())) if dic else 0)
    return 0

def start_withp(words):
    """
    Return the first two words (as a tuple) that start with the letter 'p'
    (case-insensitive) from a list of strings, where each string may
    contain multiple words.

    >>> start_withp(["Python PHP", "Java JavaScript", "c c++"])
    ('Python', 'PHP')
    """
    result = []
    for phrase in words:
        for word in phrase.split():
            if word.lower().startswith('p'):
                result.append(word)
                if len(result) == 2:
                    return tuple(result)
    return tuple(result)


if __name__ == "__main__":
    assert start_withp(["Python PHP", "Java JavaScript", "c c++"]) == ('Python', 'PHP')
    print("All tests passed.")

import heapq


def large_product(nums1, nums2, n):
    """Find the n largest products formed by picking one factor from each list.

    Computes all pairwise products a*b (a from nums1, b from nums2) and
    returns the n largest in descending order.
    """
    return heapq.nlargest(n, (a * b for a in nums1 for b in nums2))


if __name__ == "__main__":
    assert large_product([1, 2, 3, 4, 5, 6], [3, 6, 8, 9, 10, 6], 3) == [60, 54, 50]
    print("All tests passed.")

def set_left_most_unset_bit(n):
    """Set the leftmost (most significant) unset bit of n.

    Example: 10 is 1010 in binary; its leftmost unset bit is at
    position 1, so setting it yields 1110 = 14.
    """
    if n == 0:
        return 1
    # Scan from the most significant bit down to find the first unset bit.
    for i in range(n.bit_length() - 1, -1, -1):
        if not (n & (1 << i)):
            return n | (1 << i)
    # All bits within the number's length are set (e.g. 7 -> 111).
    return n


if __name__ == "__main__":
    assert set_left_most_unset_bit(10) == 14
    assert set_left_most_unset_bit(0) == 1
    assert set_left_most_unset_bit(1) == 1      # 1 has no unset bit
    assert set_left_most_unset_bit(7) == 7      # 111 has no unset bit
    assert set_left_most_unset_bit(12) == 14    # 1100 -> 1110
    print("All tests passed.")

