"""Find the maximum sum possible by using the given equation
f(n) = max(f(n/2) + f(n/3) + f(n/4) + f(n/5), n),
where the divisions are integer divisions and f(0) = 0.
"""

from functools import lru_cache


def get_max_sum(n):
    """Return the maximum value obtainable from the recurrence
    f(n) = max(f(n//2) + f(n//3) + f(n//4) + f(n//5), n).

    Uses memoized recursion; each value is computed once.
    """
    @lru_cache(maxsize=None)
    def f(k):
        if k == 0:
            return 0
        return max(f(k // 2) + f(k // 3) + f(k // 4) + f(k // 5), k)

    return f(n)


if __name__ == "__main__":
    assert get_max_sum(60) == 106
    print(get_max_sum(60))  # 106

