def sumofFactors(n):
    """Return the sum of the even factors of n."""
    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i % 2 == 0:
                total += i
            other = n // i
            if other != i and other % 2 == 0:
                total += other
        i += 1
    return total


if __name__ == "__main__":
    assert sumofFactors(18) == 26
    assert sumofFactors(30) == 48  # factors: 1,2,3,5,6,10,15,30 -> evens: 2+6+10+30
    assert sumofFactors(10) == 12  # factors: 1,2,5,10 -> evens: 2+10
    assert sumofFactors(9) == 0    # factors: 1,3,9 -> no even factors
    print("All tests passed.")

