def tuple_intersection(test_list1, test_list2):
    """
    Find the tuple intersection of elements in the given tuple lists,
    irrespective of the order of elements within each tuple.

    Tuples are considered equal if they contain the same elements in any
    order, e.g. (3, 4) matches (4, 3). The result contains the tuples as
    they appear in the first list.

    >>> tuple_intersection([(3, 4), (5, 6), (9, 10), (4, 5)],
    ...                    [(5, 4), (3, 4), (6, 5), (9, 11)]) == {(4, 5), (3, 4), (5, 6)}
    True
    """
    # Normalize each tuple by sorting its elements so order doesn't matter.
    normalized2 = {tuple(sorted(t)) for t in test_list2}

    result = set()
    for tup in test_list1:
        if tuple(sorted(tup)) in normalized2:
            result.add(tup)
    return result


if __name__ == "__main__":
    assert tuple_intersection([(3, 4), (5, 6), (9, 10), (4, 5)],
                              [(5, 4), (3, 4), (6, 5), (9, 11)]) == {(4, 5), (3, 4), (5, 6)}
    assert tuple_intersection([(1, 2), (3, 4)], [(2, 1), (4, 3)]) == {(1, 2), (3, 4)}
    assert tuple_intersection([(1, 2)], [(3, 4)]) == set()
    assert tuple_intersection([], [(1, 2)]) == set()
    print("All tests passed.")

