"""Sum of the product of consecutive binomial coefficients.

Identity: sum_{k=0}^{n-1} C(n, k) * C(n, k+1) = C(2n, n-1)

Example: n = 3 -> row is 1, 3, 3, 1
         1*3 + 3*3 + 3*1 = 15 == C(6, 2)
"""


def binomial_Coeff(n, k):
    """Compute C(n, k) iteratively."""
    if k < 0 or k > n:
        return 0
    if k > n - k:
        k = n - k
    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)
    return result


def sum_Of_product(n):
    """Find the sum of the product of consecutive binomial coefficients."""
    return binomial_Coeff(2 * n, n - 1)


