def heap_sort(nums):
    """Sort the given list in ascending order using heap sort."""
    def sift_down(start, end):
        # Sift the element at start down within nums[start:end+1]
        root = start
        while True:
            child = 2 * root + 1
            if child > end:
                break
            if child + 1 <= end and nums[child] < nums[child + 1]:
                child += 1
            if nums[root] < nums[child]:
                nums[root], nums[child] = nums[child], nums[root]
                root = child
            else:
                break

    n = len(nums)
    # Build max heap
    for start in range(n // 2 - 1, -1, -1):
        sift_down(start, n - 1)
    # Extract elements one by one
    for end in range(n - 1, 0, -1):
        nums[0], nums[end] = nums[end], nums[0]
        sift_down(0, end - 1)
    return nums

