def check_expression(exp):
    """Check if the given expression has balanced brackets.

    Supports (), {}, and []. Returns True if balanced, False otherwise.
    """
    pairs = {')': '(', '}': '{', ']': '['}
    stack = []
    for char in exp:
        if char in '([{':
            stack.append(char)
        elif char in pairs:
            if not stack or stack.pop() != pairs[char]:
                return False
    return not stack


